:root {
	/* ================================
	   AI CV ANALYZER — BLUE + GREEN
	   ================================ */

	--font-family: 'Inter', 'Open Sans', sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;

	--font-size-body: 13px;
	--font-size-label: 14px;
	--font-size-test-notice: 12px;
	--font-size-input: 14px;
	--font-size-header: 28px;
	--font-size-paragraph: 14px;
	--font-size-link: 13px;
	--font-size-error: 12px;

	/* ================================
	   COLORS
	   ================================ */

	/* Page */
	--color-background: #f0f7ff;

	/* Main Card */
	--color-card-bg: #ffffff;
	--color-card-border: #dbeafe;
	--color-card-shadow: rgba(15, 23, 42, 0.10);

	/* Blue */
	--color-primary: #2563eb;
	--color-primary-dark: #1d4ed8;
	--color-primary-light: #eff6ff;

	/* Green */
	--color-secondary: #16a34a;
	--color-secondary-dark: #15803d;
	--color-secondary-light: #f0fdf4;

	/* Text */
	--color-header: #0f172a;
	--color-label: #334155;
	--color-html-text: #475569;
	--color-header-subtext: #64748b;
	--color-link: #2563eb;

	/* Inputs */
	--color-input-border: #cbd5e1;
	--color-input-text: #1e293b;
	--color-input-bg: #ffffff;
	--color-focus-border: #2563eb;
	--color-placeholder: #94a3b8;

	/* Button */
	--color-submit-btn-bg: #2563eb;
	--color-submit-btn-text: #ffffff;
	--color-submit-btn-hover: #1d4ed8;

	/* Notice */
	--color-test-notice-text: #166534;
	--color-test-notice-bg: #f0fdf4;
	--color-test-notice-border: #bbf7d0;

	/* Error */
	--color-error: #dc2626;
	--color-required: #dc2626;

	/* Clear Button */
	--color-clear-button-bg: #64748b;

	/* ================================
	   RADIUS
	   ================================ */

	--border-radius-card: 18px;
	--border-radius-input: 10px;
	--border-radius-clear-btn: 50%;

	/* ================================
	   SPACING
	   ================================ */

	--padding-container-top: 40px;
	--padding-card: 36px;
	--padding-form-input: 14px;

	--margin-bottom-card: 20px;
	--card-margin-bottom: 20px;

	/* ================================
	   DIMENSIONS
	   ================================ */

	--container-width: 600px;
	--submit-btn-height: 52px;

	/* ================================
	   SHADOW
	   ================================ */

	--box-shadow-card:
		0 20px 50px rgba(15, 23, 42, 0.08);

	--opacity-placeholder: 0.65;
}


/* =========================================
   MAIN PAGE
   ========================================= */

html,
body {
	margin: 0;
	padding: 0;
	background:
		linear-gradient(
			135deg,
			#eff6ff 0%,
			#f8fafc 50%,
			#f0fdf4 100%
		);

	font-family: var(--font-family);
	color: var(--color-html-text);
}


/* =========================================
   FORM CARD
   ========================================= */

form {
	position: relative;

	background: rgba(255, 255, 255, 0.98);

	border: 1px solid #dbeafe;

	border-radius: var(--border-radius-card);

	box-shadow: var(--box-shadow-card);

	padding: var(--padding-card);

	overflow: hidden;
}


/* Blue + Green Top Border */

form::before {
	content: "";

	position: absolute;

	top: 0;
	left: 0;
	right: 0;

	height: 5px;

	background:
		linear-gradient(
			90deg,
			#2563eb 0%,
			#3b82f6 45%,
			#16a34a 100%
		);
}


/* =========================================
   HEADER
   ========================================= */

h1 {
	color: var(--color-header);

	font-size: 28px;

	font-weight: 700;

	letter-spacing: -0.6px;

	margin-bottom: 8px;
}


h2 {
	color: var(--color-header);

	font-weight: 700;
}


/* Header description */

p {
	line-height: 1.6;
}


/* =========================================
   LABELS
   ========================================= */

label {
	display: block;

	color: var(--color-label);

	font-size: 14px;

	font-weight: 600;

	margin-bottom: 7px;
}


/* =========================================
   INPUTS
   ========================================= */

input,
textarea,
select {
	width: 100%;

	box-sizing: border-box;

	background: #ffffff;

	color: var(--color-input-text);

	border: 1px solid var(--color-input-border);

	border-radius: var(--border-radius-input);

	padding: var(--padding-form-input);

	font-family: var(--font-family);

	font-size: 14px;

	transition:
		border-color 0.2s ease,
		box-shadow 0.2s ease,
		transform 0.2s ease;
}


/* Focus */

input:focus,
textarea:focus,
select:focus {
	outline: none;

	border-color: var(--color-primary);

	box-shadow:
		0 0 0 4px rgba(37, 99, 235, 0.10);
}


/* =========================================
   CV UPLOAD AREA
   ========================================= */

input[type="file"] {
	background: linear-gradient(
		135deg,
		#eff6ff,
		#f0fdf4
	);

	border: 2px dashed #93c5fd;

	padding: 18px;

	cursor: pointer;

	color: #475569;

	transition: all 0.25s ease;
}


input[type="file"]:hover {
	border-color: #16a34a;

	background: #f0fdf4;

	box-shadow:
		0 6px 20px rgba(22, 163, 74, 0.08);
}


/* =========================================
   TEXTAREA — JOB DESCRIPTION
   ========================================= */

textarea {
	min-height: 150px;

	resize: vertical;
}


/* =========================================
   SUBMIT BUTTON
   ========================================= */

button[type="submit"] {
	width: 100%;

	height: var(--submit-btn-height);

	background:
		linear-gradient(
			135deg,
			#2563eb 0%,
			#1d4ed8 55%,
			#16a34a 100%
		);

	color: #ffffff;

	border: none;

	border-radius: 10px;

	font-size: 15px;

	font-weight: 700;

	letter-spacing: 0.2px;

	cursor: pointer;

	box-shadow:
		0 8px 20px rgba(37, 99, 235, 0.20);

	transition: all 0.25s ease;
}


button[type="submit"]:hover {
	transform: translateY(-2px);

	box-shadow:
		0 12px 28px rgba(37, 99, 235, 0.25);
}


button[type="submit"]:active {
	transform: translateY(0);
}


/* =========================================
   NOTICE / INFO BOX
   ========================================= */

.test-notice {
	background:
		linear-gradient(
			135deg,
			#eff6ff,
			#f0fdf4
		);

	border: 1px solid #bbf7d0;

	color: #166534;

	border-radius: 10px;

	padding: 14px 18px;
}


/* =========================================
   LINKS
   ========================================= */

a {
	color: #2563eb;

	font-weight: 600;

	text-decoration: none;

	transition: color 0.2s ease;
}


a:hover {
	color: #16a34a;
}


/* =========================================
   ERROR
   ========================================= */

.error {
	color: var(--color-error);

	font-size: 12px;
}


/* =========================================
   REQUIRED FIELD
   ========================================= */

.required {
	color: #dc2626;
}


/* =========================================
   FOOTER BRANDING
   ========================================= */

form::after {
	content: "Created by JZ Pvt Ltd";

	display: block;

	text-align: center;

	margin-top: 30px;

	padding-top: 18px;

	border-top: 1px solid #e2e8f0;

	color: #64748b;

	font-size: 12px;

	font-weight: 600;

	letter-spacing: 0.4px;
}


/* =========================================
   MOBILE RESPONSIVE
   ========================================= */

@media (max-width: 600px) {

	form {
		margin: 15px;

		padding: 24px;

		border-radius: 14px;
	}

	h1 {
		font-size: 24px;
	}

	--container-width: 100%;
}
